def test_order_history_includes_cancelled_orders(shop):
    oid1 = order(shop, "c1", ("BOOK", 1)).body["order_id"]
    oid2 = order(shop, "c1", ("PEN", 1)).body["order_id"]
    shop.orders.handle_cancel(oid1)

    response = shop.insights.handle_order_history("c1")
    assert response.status == 200
    orders = response.body["orders"]
    assert len(orders) == 2
    assert orders[0]["order_id"] == oid2
    assert orders[0]["status"] == "placed"
    assert orders[1]["order_id"] == oid1
    assert orders[1]["status"] == "cancelled"


def test_lifetime_value_unknown_customer(shop):
    response = shop.insights.handle_lifetime_value("nobody")
    assert response.status == 404
    assert response.body == {"error": "customer not found"}


def test_lifetime_value_customer_with_no_orders(shop):
    response = shop.insights.handle_lifetime_value("c1")
    assert response.status == 200
    assert response.body == {"customer_id": "c1", "order_count": 0, "lifetime_value_cents": 0}


def test_lifetime_value_single_order(shop):
    order(shop, "c1", ("BOOK", 2))

    response = shop.insights.handle_lifetime_value("c1")
    assert response.status == 200
    assert response.body == {"customer_id": "c1", "order_count": 1, "lifetime_value_cents": 5000}


def test_lifetime_value_multiple_orders(shop):
    order(shop, "c1", ("BOOK", 2))
    order(shop, "c1", ("PEN", 3))

    response = shop.insights.handle_lifetime_value("c1")
    assert response.status == 200
    assert response.body == {"customer_id": "c1", "order_count": 2, "lifetime_value_cents": 5900}


def test_lifetime_value_includes_discount(shop):
    order(shop, "c2", ("LAMP", 2))

    response = shop.insights.handle_lifetime_value("c2")
    assert response.status == 200
    assert response.body == {"customer_id": "c2", "order_count": 1, "lifetime_value_cents": 10200}


def test_lifetime_value_excludes_cancelled_orders(shop):
    oid1 = order(shop, "c1", ("BOOK", 1)).body["order_id"]
    order(shop, "c1", ("PEN", 1))
    shop.orders.handle_cancel(oid1)

    response = shop.insights.handle_lifetime_value("c1")
    assert response.status == 200
    assert response.body == {"customer_id": "c1", "order_count": 1, "lifetime_value_cents": 300}


def test_lifetime_value_mixed_placed_and_cancelled(shop):
    oid1 = order(shop, "c1", ("BOOK", 2)).body["order_id"]
    order(shop, "c1", ("LAMP", 1))
    oid3 = order(shop, "c1", ("PEN", 1)).body["order_id"]
    shop.orders.handle_cancel(oid1)

    response = shop.insights.handle_lifetime_value("c1")
    assert response.status == 200
    assert response.body == {"customer_id": "c1", "order_count": 2, "lifetime_value_cents": 6300}


