"""Customer insights service."""

from __future__ import annotations

from dataclasses import dataclass

from orders.application.customer_service import CustomerService
from orders.application.order_service import OrderService


@dataclass(frozen=True)
class CustomerLifetimeValue:
    customer_id: str
    name: str
    lifetime_value_cents: int


class InsightsService:
    def __init__(self, order_service: OrderService, customer_service: CustomerService) -> None:
        self._order_service = order_service
        self._customer_service = customer_service

    def get_lifetime_value(self, customer_id: str) -> int:
        orders = self._order_service.list_for_customer(customer_id)
        lifetime_value_cents = 0
        for order in orders:
            if order.status != "cancelled":
                summary = self._order_service.summarize(order)
                lifetime_value_cents += summary.total_cents
        return lifetime_value_cents

    def get_top_customers(self, limit: int) -> list[CustomerLifetimeValue]:
        customers = self._customer_service.list_all()

        customer_values = []
        for customer in customers:
            lifetime_value = self.get_lifetime_value(customer.customer_id)
            if lifetime_value > 0:
                customer_values.append(CustomerLifetimeValue(
                    customer.customer_id,
                    customer.name,
                    lifetime_value
                ))

        # Sort by lifetime_value descending, then by customer_id
        customer_values.sort(key=lambda c: (-c.lifetime_value_cents, c.customer_id))

        return customer_values[:limit]

